import { z } from 'zod'
// Side effect: zod answers in Spanish. Imported per module, not only from
// index, so importing this file directly cannot skip it.
import './locale'

const emailSchema = z.email('Ingresa un correo electrónico válido')

/**
 * A new account, an administrator or a company's user: the account and its
 * access in one step. Only the address travels — the password is generated by
 * the API and shown once.
 */
export const createAccountSchema = z.object({ email: emailSchema })

export type CreateAccountInput = z.infer<typeof createAccountSchema>

/**
 * What the administrator reads once and hands over. It is not stored anywhere,
 * so closing the dialog that shows it is the end of it.
 */
export const temporaryPasswordSchema = z.object({
  email: z.string(),
  password: z.string(),
})

export type TemporaryPassword = z.infer<typeof temporaryPasswordSchema>

/**
 * What makes a password strong enough, one rule per line the panel shows under
 * the field. The schema below is built from this same list, so the checklist on
 * screen and what the API accepts cannot disagree.
 *
 * "Special" is anything that is not an unaccented letter or a digit: a space,
 * `ñ` and `é` count, which is what a person typing in Spanish expects.
 */
export const PASSWORD_RULES = [
  { label: 'Al menos 8 caracteres', pattern: /^.{8,}$/u },
  { label: 'Una letra mayúscula', pattern: /[A-Z]/ },
  { label: 'Una letra minúscula', pattern: /[a-z]/ },
  { label: 'Un número', pattern: /\d/ },
  { label: 'Un carácter especial, como ! @ # $ % o *', pattern: /[^A-Za-z0-9]/ },
] as const

const passwordSchema = PASSWORD_RULES.reduce(
  (schema, rule) =>
    schema.regex(rule.pattern, `La contraseña debe tener: ${rule.label.toLowerCase()}`),
  // 72 is bcrypt's limit: Supabase Auth would silently ignore whatever came
  // after it, so a longer password would not be the password it looks like.
  z.string().max(72, 'La contraseña no puede tener más de 72 caracteres'),
)

export const changePasswordSchema = z.object({ password: passwordSchema })

export type ChangePasswordInput = z.infer<typeof changePasswordSchema>

export const passwordResetRequestSchema = z.object({ email: emailSchema })

export type PasswordResetRequestInput = z.infer<typeof passwordResetRequestSchema>

export const userCompanySchema = z.object({
  id: z.uuid(),
  name: z.string(),
})

/** One account on the platform, as the platform's users tab lists it. */
export const platformUserSchema = z.object({
  userId: z.uuid(),
  email: z.string().nullable(),
  createdAt: z.string(),
  lastSignInAt: z.string().nullable(),
  /** The active ADMIN grant, which is what revoking needs; null for everyone else. */
  adminGrantId: z.uuid().nullable(),
  companies: z.array(userCompanySchema),
  /** When the person asked to reset their password, while nobody has resolved it. */
  resetRequestedAt: z.string().nullable(),
  mustChangePassword: z.boolean(),
  /** Left with neither the role nor a company: it cannot sign in. */
  isBlocked: z.boolean(),
})

export type PlatformUser = z.infer<typeof platformUserSchema>
